322			{"empty source over bad target", graph, "", "ghost", "dataset name is required"},
323			{"missing source first", graph, "ghost", "", "dataset not found: ghost"},
324			{"missing source over missing target", graph, "ghost", "phantom", "dataset not found: ghost"},
325			{"source valid then empty target", graph, "source", "", "dataset name is required"},
326			{"source valid then missing target", graph, "source", "ghost", "dataset not found: ghost"},
327			{"empty graph source", map[string]*Lineage{}, "source", "report", "dataset not found: source"},
328			{"nil graph source", nil, "source", "report", "dataset not found: source"},
329		}
330		for _, tc := range cases {
331			t.Run(tc.name, func(t *testing.T) {
332				out, err := ExportSourceTargetLineage(tc.graph, tc.source, tc.target)
333				if err == nil {
334					t.Fatalf("(%q, %q) succeeded with %q, want error %q",
335						tc.source, tc.target, out, tc.wantErr)
336				}
337				if err.Error() != tc.wantErr {
338					t.Errorf("error = %q, want %q", err, tc.wantErr)
339				}
340				if out != "" {
341					t.Errorf("failed export returned partial content %q, want empty string", out)
342				}
343			})
344		}
