441	// When several selected names are invalid, the string-smallest one is
442	// reported identically under reversed registration and upstream-list orders.
443	func TestExportSourceTargetLineageFirstInvalidNameOrderIndependent(t *testing.T) {
444		fe := "x\xfe"
445		ff := "x\xff"
446		first := buildRegisteredGraph(t, [][]string{
447			{"source"},
448			{fe, "source"},
449			{ff, "source"},
450			{"report", fe, ff},
