188	// The ancestor probe resolves shared lineage once per registration: several
189	// candidate starts that come from the same source and merge along the way reuse
190	// cached conclusions instead of re-walking the common nodes.
191	func TestAncestorProbeSharesWorkAcrossCandidates(t *testing.T) {
192		graph := map[string]*Lineage{}
193		mustRegister(t, graph, "src")
194		mustRegister(t, graph, "a", "src")
195		mustRegister(t, graph, "b", "src")
196		mustRegister(t, graph, "merge", "a", "b")
197		mustRegister(t, graph, "other")
198	
199		probe := newAncestorProbe(graph, "src")
200		if !probe.canReach("merge") {
201			t.Fatal("merge should reach src through either branch")
202		}
203		// merge's walk already resolved a and b; asking about them again must be
204		// answered from the cache, adding no new traversal.
205		if !probe.canReach("a") || !probe.canReach("b") {
206			t.Fatal("memoized answers disagree: a and b both reach src")
207		}
208		if probe.canReach("other") {
209			t.Fatal("other does not reach src")
210		}
211		if got, want := len(probe.resolved), 4; got != want {
212			t.Fatalf("resolved %d nodes %v, want %d (merge,a,b,other); shared ancestry must not be re-walked",
213				got, probe.resolved, want)
214		}
215	
216		// A node disconnected from the target probed from two starts that merge on
217		// a common non-reaching ancestor is likewise traversed once.
218		probe = newAncestorProbe(graph, "other")
219		if probe.canReach("merge") || probe.canReach("a") || probe.canReach("b") {
220			t.Fatal("nothing derived from src reaches other")
221		}
222		if got, want := len(probe.resolved), 4; got != want {
223			t.Fatalf("resolved %d nodes %v, want %d (merge,a,b,src)", got, probe.resolved, want)
224		}
225	}
