	impacts, err := Impacts(graph, "old")
	if err != nil {
		t.Fatalf("Impacts(old) after losing its only downstream: %v", err)
	}
	if impacts == nil || len(impacts) != 0 {
		t.Fatalf("want empty non-nil list from old, got %v", impacts)
